class Spinda:
    def __init__(self,PID='',shash=''):
        if (PID != ''):
            self.PID = PID
            self.coords = PID_to_Coordinates(PID)
            self.pattern = color_spinda(self.coords)[0]
            self.shash = spinda_to_hash(self.pattern)
        else:
            self.PID = "UNKNOWN"
            self.shash = shash
            self.pattern = hash_to_spinda(shash)
    
    def draw(self,DIR='',fname=''):
        if fname == '':
            draw_spinda(self.pattern, self.PID, DIR)
        else:
            draw_spinda(self.pattern, fname, DIR)


def is_dupe_coords(coords):
    # Check for Single Dupe Coords:
    for i in (1,3):
        if coords[i-1] in Single_Dupes[i]:
            return True
    # Check for Double Dupe Coords:
    if (coords[1-1], coords[3-1]) in DD13 or\
       (coords[2-1], coords[4-1]) in DD24 or\
       (coords[3-1], coords[4-1]) in DD34:
        return True
    return False

def PID_to_Coordinates(PID):
    '''STR -> ((INT, INT), (INT, INT), (INT, INT), (INT, INT))
    Takes a STR representation of a Hexadecimal number with no base identifier and returns a tuple of coordinates.
    Each cooridnate corresponds to the upper left bounding box of one Spot
    Returns tuple in order of:
    ((Top Left Spot Coords Spot_1), (Top Right Spot Coords Spot_2), (Bottom Left Coords Spot_3), (Bottom Right Coords Spot_4))
    Coordinates are in the order of X, Y
    '''
    PID = PID.lower()
    # Gather Coordinates
    # Top Left Coord is associated with the last Nibbles of the PID
    # No additional transposition is applied to the top left spot
    TL = (int(PID[-1], 16), int(PID[-2], 16))
    # Top Right Coordinate is assosciated with the 5th and 6th nibbles of the PID
    # Transpose of [24][1] applied to the coordinates of the Top Right Spot
    TR = (int(PID[-3], 16) + 24, int(PID[-4], 16) + 1)
    # Bottom Left Coordinate is associated with the 3rd and 4th nibbles of the PID
    # Transpose of [6][18] applied to the coordinates of the Bottom Left Spot
    BL = (int(PID[3], 16) + 6, int(PID[2], 16) + 18)
    # Bottom Right coordinate is associated with the 1st and 2nd nibbles of the PID
    # Transpose of [18][19] applied to the coordinates of the Bottom Right Spot
    BR = (int(PID[1], 16) + 18, int(PID[0], 16) + 19)
    return (TL, TR, BL, BR)

def color_spinda(coord,pattern=None, drawn=False):
    if pattern is None:
        spinda = new_spinda_pattern()
    else:
        spinda = pattern
    # Color in Each Spot
    overlap = []
    overlap.append(color_spot(coord[0], spinda, all_spots[0],drawn))
    overlap.append(color_spot(coord[1], spinda, all_spots[1],drawn))
    overlap.append(color_spot(coord[2], spinda, all_spots[2],drawn))
    overlap.append(color_spot(coord[3], spinda, all_spots[3],drawn))
    return (spinda, overlap)

def color_spot(coords, spinda, spot, drawn=False):
    # Colour in each pixel covered by the current spot.
    
    #check for overlap
    overlap = False
    for y in range(0, len(spot)):
        for x in range(0, len(spot[0])):
            if spot[y][x] == 1 and ((draw_coords is None) or ((coords[0]+x, coords[1]+y) in draw_coords)):
                if drawn and spinda[coords[1]+y][coords[0]+x] > 1:
                    overlap = True                
                spinda[coords[1]+y][coords[0]+x] += spot[y][x]
                if not drawn and spinda[coords[1]+y][coords[0]+x] > 1:
                    overlap = True
    return overlap

