def base36encode(number, alphabet='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'):
    """Converts an integer to a base36 string."""
    if not isinstance(number, int):
        raise TypeError('number must be an integer')
 
    base36 = ''

    if 0 <= number < len(alphabet):
        '0'*(114-len(base36)) + base36
 
    while number != 0:
        number, i = divmod(number, len(alphabet))
        base36 = alphabet[i] + base36
 
    return '0'*(114-len(base36)) + base36

def int2PID(num):
    num = hex(num)[2:]
    num = '0'*(8-len(num)) + num
    return num

def deep_maximum(data):
    """
    Recursively finds the maximum value in a nested list or a single number.
    """
    if isinstance(data, list):
        if not data:
            return float('-inf')  # Return negative infinity for empty list
        return max(deep_maximum(item) for item in data)
    else:
        return data



