def classify_Spinda(spinda):
    ''' Take in a Spinda Pattern and return its classification code '''
    PID = spinda.PID
    coord = PID_to_Coordinates(PID)
    pat1 = new_spinda_pattern()
    pat2 = new_spinda_pattern()
    color_spot(coord[0], pat1, all_spots[0])
    color_spot(coord[1], pat2, all_spots[1])    
    L = "UNDEFINED"
    R = "UNDEFINED"
    # TEST CENTER
    # LEFT
    t = True
    for i in YELLOW_coords_L:
        if pat1[i[0]][i[1]] == 0:
            t = False
    if t:
        L = "C"
    # RIGHT
    t = True
    for i in YELLOW_coords_R:
        if pat2[i[0]][i[1]] == 0:
            t = False
    if t:
        R = "C"    
    
    # Hiding
    if L == "UNDEFINED":
        s = recursive_sum(pat1)
        if s == 0:
            L = "I"
        elif s < 10:
            L = "H"
    if R == "UNDEFINED":
        s = recursive_sum(pat2)
        if s == 0:
            R = "I"
        elif s < 10:
            R = "H"        
    
    # DOWN
    if L == "UNDEFINED":
        for coord in ORANGE_coords:
            if pat1[coord[0]][coord[1]] != 0:
                L = "D"
    if R == "UNDEFINED":
        for coord in ORANGE_coords:
            if pat2[coord[0]][coord[1]] != 0:
                R = "D"
    # BOTH
    if L == "UNDEFINED":
        UP = False
        SIDE = False
        for coord in BLUE_coords:
            if pat1[coord[0]][coord[1]] != 0:
                UP = True
        for coord in RED_coords:
            if pat1[coord[0]][coord[1]] != 0:
                SIDE = True
        if UP and SIDE:
            L = "B"
    
    if R == "UNDEFINED":
        UP = False
        SIDE = False
        for coord in BLUE_coords:
            if pat2[coord[0]][coord[1]] != 0:
                UP = True
        for coord in RED_coords:
            if pat2[coord[0]][coord[1]] != 0:
                SIDE = True        
        if UP and SIDE:
            R = "B"   
    
    #PINK
    if L == "UNDEFINED":
        for coord in PINK_coords:
            if pat1[coord[0]][coord[1]] != 0:    
                L = "R"
    # GREEN
    if R == "UNDEFINED":
        for coord in GREEN_coords:
            if pat2[coord[0]][coord[1]] != 0:
                R = "L"
    #UP
    if L == "UNDEFINED":
        for coord in BLUE_coords:
            if pat1[coord[0]][coord[1]] != 0:
                L = "U"
    if R == "UNDEFINED":
        for coord in BLUE_coords:
            if pat2[coord[0]][coord[1]] != 0:
                R = "U"    
    # L/R
    if L == "UNDEFINED":
        p = 0
        c = 0
        for coord in PURPLE_coords:
            if pat1[coord[0]][coord[1]] != 0:
                p += 1
        for coord in CYAN_coords:
            if pat1[coord[0]][coord[1]] != 0:
                c += 1
        if p > c:
            L = "L"
        else:
            L = "R"
    if R == "UNDEFINED":
        p = 0
        c = 0
        for coord in PURPLE_coords:
            if pat2[coord[0]][coord[1]] != 0:
                p += 1
        for coord in CYAN_coords:
            if pat2[coord[0]][coord[1]] != 0:
                c += 1
        if p > c:
            R = "L"
        else:
            R = "R"
    if L == "UNDEFINED":
        L  = "_HUH_"
    if R == "UNDEFINED":
        R = "_HUH_"
    if int(PID[-2:], 16) >= 127:
        g = "M"
    else:
        g = "F"  
    return (g+L+R)

def read_Bytes():
    f3=open("All_MirageBytes.txt", "r")
    lst = []
    for line in f3:
        line = line.rstrip()
        lst.append(line[-4:])
    return lst

def make_mirages():
    mBytes = read_Bytes()
    i = 0
    for day in mBytes:
        s = Spinda("0000" + day)
        SID = classify_Spinda(s)
        os.makedirs("M_SPIN/"+SID, exist_ok=True)
        s.draw("M_SPIN/"+SID+"/", "DAY_" +str(i) +"_" + SID + "_" + day)
        i += 1

